def findLonelyPixel(picture):
    if not picture or not picture[0]:
        return 0
    m, n = len(picture), len(picture[0])
    rows = [0] * m
    cols = [0] * n
    # Count 'B's per row and column
    for i in range(m):
        for j in range(n):
            if picture[i][j] == 'B':
                rows[i] += 1
                cols[j] += 1
    # Find lonely pixels
    result = 0
    for i in range(m):
        for j in range(n):
            if picture[i][j] == 'B' and rows[i] == 1 and cols[j] == 1:
                result += 1
    return result
